import clsx from 'clsx';
import React, { ReactElement, ReactNode, ReactText } from 'react';

import { highlightCSS } from './Highlight.sty.js';
import type { WithChildren } from '../core/types/with-children.js';

export interface HighlightProps extends WithChildren {
  /**
   * Either a substring or an array of multiple different substrings that
   * should be highlighted in the projected content.
   * Every occurrence of the string(s) is highlighted accordingly.
   */
  term: string | string[];

  /**
   * Property that determines whether the highlighting search is case-sensitive.
   * If set to `true`, the component searches for case sensitive occurrences.
   * @defaultValue false
   */
  caseSensitive?: boolean;
}

const HTML_CHARS_OVERRIDES: [RegExp, string][] = [
  [/&lt;/g, '<'],
  [/&gt;/g, '>'],
  [/&amp;/g, '&'],
  [/&nbsp;/g, ' '],
];

/** Escapes all characters that could be dangerous for a regular expression */
function escapeRegExp(text: string): string {
  return text.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'); // $& means the whole matched string
}

/** Highlights all occurences of a list of terms within a ReactNode. */
function highlightChildren(
  children: ReactNode,
  term: string | string[],
  caseSensitive: boolean,
) {
  const terms = (() => {
    if (Array.isArray(term)) {
      return term.filter((t) => t);
    }

    return term ? [term] : [];
  })();

  return terms.length > 0
    ? React.Children.map(children, (child: ReactNode) =>
        highlightRecursive(child, terms, caseSensitive),
      )
    : children;
}

/**
 * Iterates over all children of a ReactNode recursively to look
 * for a list of terms and highlights them.
 */
function highlightRecursive(
  sourceElement: ReactNode,
  terms: string[],
  caseSensitive: boolean,
): ReactNode {
  if (!sourceElement) {
    return sourceElement;
  }

  if (React.isValidElement(sourceElement)) {
    const children = React.Children.map(sourceElement.props.children, (child) =>
      highlightRecursive(child, terms, caseSensitive),
    );

    return React.cloneElement(sourceElement, sourceElement.props, children);
  }

  return highlightLeafElement(sourceElement as ReactText, terms, caseSensitive);
}

/** Highlights parts of the text that match a certain group of terms. */
function highlightLeafElement(
  textContent: ReactText,
  terms: string[],
  caseSensitive: boolean,
): ReactNode {
  if (terms.length === 0) {
    return textContent;
  }

  const sanitizedTextContent = HTML_CHARS_OVERRIDES.reduce(
    (text, [needle, replacement]) => text.replace(needle, replacement),
    `${textContent}`,
  );
  const termsInLowerCase = terms.map((t) => t.toLowerCase());

  return getTextTokens(sanitizedTextContent, terms, caseSensitive).map(
    (token: string) =>
      termsInLowerCase.includes(token.toLowerCase()) ? (
        <mark role="mark" className={clsx(highlightCSS)}>
          {token}
        </mark>
      ) : (
        <span>{token}</span>
      ),
  );
}

/**
 * Splits text into an array of strings where a given list of terms
 * acts as separator strings.
 */
function getTextTokens(
  textContent: ReactText,
  terms: string[],
  caseSensitive: boolean,
): string[] {
  const flags = caseSensitive ? 'gm' : 'gmi';
  const regExp = new RegExp(
    `(${terms.map((t) => escapeRegExp(t)).join('|')})`,
    flags,
  );

  return textContent
    .toString()
    .split(regExp)
    .filter((s) => s.length > 0);
}

/**
 * Use the `Highlight` component to highlight one or more substrings within a
 * text.
 */
export const Highlight = (props: HighlightProps): ReactElement => {
  const { children, term, caseSensitive = false } = props;

  return <>{highlightChildren(children, term, caseSensitive)}</>;
};

Highlight.displayName = 'Highlight';
